1	import { useEffect, useState } from 'react';
2	import { GameProvider, useGame } from './context/GameContext';
3	import { ChessBoardPanel } from './components/ChessBoardPanel';
4	import { VideoPanel } from './components/VideoPanel';
5	import { ChatPanel } from './components/ChatPanel';
6	import { Controls } from './components/Controls';
7	import './App.css';
8	
9	function AppContent() {
10	  const { connect, gameState } = useGame();
11	  const [isConnecting, setIsConnecting] = useState(true);
12	
13	  useEffect(() => {
14	    const initConnection = async () => {
15	      try {
16	        await connect();
17	        setIsConnecting(false);
18	      } catch (error) {
19	        console.error('Failed to connect:', error);
20	        setIsConnecting(false);
21	      }
22	    };
23	
24	    initConnection();
25	  }, [connect]);
26	
27	  if (isConnecting) {
28	    return (
29	      <div className="app loading-screen">
30	        <div className="loading-content">
31	          <div className="logo">
32	            <h1>CHESS ROULETTE</h1>
33	            <p className="subtitle">CODING CHALLENGE</p>
34	          </div>
35	          <div className="loading-spinner">
36	            <div className="spinner"></div>
37	          </div>
38	          <p>Connecting to server...</p>
39	        </div>
40	      </div>
41	    );
42	  }
43	
44	  return (
45	    <div className="app">
46	      <header className="app-header">
47	        <div className="logo">
48	          <h1>CHESS ROULETTE</h1>
49	          <p className="subtitle">CODING CHALLENGE</p>
50	        </div>
51	        <div className="header-info">
52	          <div className="info-badge">
53	            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
54	              <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
55	              <circle cx="9" cy="7" r="4" />
56	              <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
57	              <path d="M16 3.13a4 4 0 0 1 0 7.75" />
58	            </svg>
59	            <span>1v1</span>
60	          </div>
61	          <div className="info-badge">
62	            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
63	              <circle cx="12" cy="12" r="10" />
64	              <polyline points="12 6 12 12 16 14" />
65	            </svg>
66	            <span>Real-time</span>
67	          </div>
68	        </div>
69	      </header>
70	
71	      <main className="app-main">
72	        <div className="game-area">
73	          <ChessBoardPanel />
74	        </div>
75	
76	        {gameState.isMatched && (
77	          <div className="video-area">
78	            <div className="video-panels">
79	              <VideoPanel isLocal={true} />
80	              <VideoPanel isLocal={false} />
81	            </div>
82	          </div>
83	        )}
84	
85	        <div className="sidebar">
86	          <Controls />
87	          {gameState.isMatched && <ChatPanel />}
88	        </div>
89	      </main>
90	
91	      <footer className="app-footer">
92	        <p>Built with React, TypeScript, Socket.io & WebRTC</p>
93	      </footer>
94	    </div>
95	  );
96	}
97	
98	function App() {
99	  return (
100	    <GameProvider>
101	      <AppContent />
102	    </GameProvider>
103	  );
104	}
105	
106	export default App;

