1	import { createContext, useContext, useState, useCallback, useEffect, ReactNode } from 'react';
2	import { Chess, Move as ChessMove } from 'chess.js';
3	import { socketService } from '../services/socket';
4	import { webRTCService } from '../services/webrtc';
5	import { GameState, ChatMessage } from '../types';
6	
7	interface GameContextType {
8	  gameState: GameState;
9	  chess: Chess;
10	  connect: () => Promise<void>;
11	  disconnect: () => void;
12	  joinQueue: () => void;
13	  leaveQueue: () => void;
14	  makeMove: (move: ChessMove) => void;
15	  resign: () => void;
16	  sendChatMessage: (message: string) => void;
17	  chatMessages: ChatMessage[];
18	  localVideoStream: MediaStream | null;
19	  remoteVideoStream: MediaStream | null;
20	  isVideoEnabled: boolean;
21	  isAudioEnabled: boolean;
22	  toggleVideo: () => void;
23	  toggleAudio: () => void;
24	  switchCamera: () => void;
25	  error: string | null;
26	  clearError: () => void;
27	}
28	
29	const GameContext = createContext<GameContextType | undefined>(undefined);
30	
31	const INITIAL_GAME_STATE: GameState = {
32	  isConnected: false,
33	  isQueued: false,
34	  isMatched: false,
35	  isPlaying: false,
36	  game: null,
37	  playerColor: null,
38	  opponentId: null,
39	  fen: 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
40	  lastMove: null,
41	  isMyTurn: false,
42	  gameOver: false,
43	  winner: null,
44	  gameOverReason: null,
45	};
46	
47	export function GameProvider({ children }: { children: ReactNode }) {
48	  const [gameState, setGameState] = useState<GameState>(INITIAL_GAME_STATE);
49	  const [chess] = useState(new Chess());
50	  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
51	  const [localVideoStream, setLocalVideoStream] = useState<MediaStream | null>(null);
52	  const [remoteVideoStream, setRemoteVideoStream] = useState<MediaStream | null>(null);
53	  const [isVideoEnabled, setIsVideoEnabled] = useState(true);
54	  const [isAudioEnabled, setIsAudioEnabled] = useState(true);
55	  const [error, setError] = useState<string | null>(null);
56	
57	  const clearError = useCallback(() => setError(null), []);
58	
59	  const connect = useCallback(async () => {
60	    try {
61	      await socketService.connect();
62	      setGameState((prev) => ({ ...prev, isConnected: true }));
63	    } catch (err) {
64	      setError('Failed to connect to server');
65	      throw err;
66	    }
67	  }, []);
68	
69	  const disconnect = useCallback(() => {
70	    socketService.disconnect();
71	    webRTCService.close();
72	    setGameState(INITIAL_GAME_STATE);
73	    setChatMessages([]);
74	    setLocalVideoStream(null);
75	    setRemoteVideoStream(null);
76	  }, []);
77	
78	  const joinQueue = useCallback(() => {
79	    socketService.joinQueue();
80	    setGameState((prev) => ({ ...prev, isQueued: true }));
81	  }, []);
82	
83	  const leaveQueue = useCallback(() => {
84	    socketService.leaveQueue();
85	    setGameState((prev) => ({ ...prev, isQueued: false }));
86	  }, []);
87	
88	  const makeMove = useCallback((move: ChessMove) => {
89	    if (!gameState.game || !gameState.isPlaying) return;
90	
91	    try {
92	      const chessMove = chess.move(move);
93	      if (chessMove) {
94	        const fen = chess.fen();
95	        socketService.makeMove(gameState.game.id, chessMove.san, fen);
96	        
97	        setGameState((prev) => ({
98	          ...prev,
99	          fen,
100	          lastMove: { from: move.from, to: move.to },
101	          isMyTurn: false,
102	        }));
103	
104	        // Check for game over
105	        if (chess.isGameOver()) {
106	          let winner: 'white' | 'black' | 'draw' | null = null;
107	          let reason = '';
108	
109	          if (chess.isCheckmate()) {
110	            winner = chess.turn() === 'w' ? 'black' : 'white';
111	            reason = 'checkmate';
112	          } else if (chess.isDraw()) {
113	            reason = 'draw';
114	          } else if (chess.isStalemate()) {
115	            reason = 'stalemate';
116	          }
117	
118	          setGameState((prev) => ({
119	            ...prev,
120	            gameOver: true,
121	            winner,
122	            gameOverReason: reason,
123	          }));
124	        }
125	      }
126	    } catch (err) {
127	      console.error('Invalid move:', err);
128	    }
129	  }, [gameState.game, gameState.isPlaying, chess]);
130	
131	  const resign = useCallback(() => {
132	    if (!gameState.game) return;
133	    socketService.resign(gameState.game.id);
134	    setGameState((prev) => ({
135	      ...prev,
136	      gameOver: true,
137	      winner: prev.playerColor === 'white' ? 'black' : 'white',
138	      gameOverReason: 'resignation',
139	    }));
140	  }, [gameState.game, gameState.playerColor]);
141	
142	  const sendChatMessage = useCallback((message: string) => {
143	    if (!gameState.game) return;
144	    socketService.sendChatMessage(gameState.game.id, message);
145	    setChatMessages((prev) => [
146	      ...prev,
147	      { from: socketService.getId() || 'me', message, timestamp: Date.now(), isMe: true },
148	    ]);
149	  }, [gameState.game]);
150	
151	  const toggleVideo = useCallback(() => {
152	    webRTCService.toggleVideo(!isVideoEnabled);
153	    setIsVideoEnabled(!isVideoEnabled);
154	  }, [isVideoEnabled]);
155	
156	  const toggleAudio = useCallback(() => {
157	    webRTCService.toggleAudio(!isAudioEnabled);
158	    setIsAudioEnabled(!isAudioEnabled);
159	  }, [isAudioEnabled]);
160	
161	  const switchCamera = useCallback(async () => {
162	    await webRTCService.switchCamera();
163	  }, []);
164	
165	  // Set up socket event listeners
166	  useEffect(() => {
167	    const unsubscribers: (() => void)[] = [];
168	
169	    const setupListeners = () => {
170	      unsubscribers.push(
171	        socketService.on('queueJoined', (_data: any) => {
172	          console.log('Queue joined');
173	        })
174	      );
175	
176	      unsubscribers.push(
177	        socketService.on('queueLeft', () => {
178	          setGameState((prev) => ({ ...prev, isQueued: false }));
179	        })
180	      );
181	
182	      unsubscribers.push(
183	        socketService.on('matchFound', async (data: { gameId: string; color: 'white' | 'black'; opponentId: string }) => {
184	          console.log('Match found:', data);
185	          
186	          setGameState((prev) => ({
187	            ...prev,
188	            isMatched: true,
189	            isQueued: false,
190	            game: {
191	              id: data.gameId,
192	              white: data.color === 'white' ? socketService.getId()! : data.opponentId,
193	              black: data.color === 'black' ? socketService.getId()! : data.opponentId,
194	              whiteSocketId: '',
195	              blackSocketId: '',
196	              moves: [],
197	              status: 'waiting',
198	              createdAt: Date.now(),
199	            },
200	            playerColor: data.color,
201	            opponentId: data.opponentId,
202	          }));
203	
204	          // Initialize WebRTC
205	          try {
206	            const localStream = await webRTCService.initialize(
207	              (remoteStream) => {
208	                setRemoteVideoStream(remoteStream);
209	              },
210	              (candidate) => {
211	                if (gameState.game) {
212	                  socketService.sendWebRTCIceCandidate(gameState.game.id, candidate, socketService.getId()!);
213	                }
214	              }
215	            );
216	            setLocalVideoStream(localStream);
217	
218	            // Create offer if white (first player)
219	            if (data.color === 'white') {
220	              const offer = await webRTCService.createOffer();
221	              socketService.sendWebRTCOffer(data.gameId, offer, socketService.getId()!);
222	            }
223	          } catch (err) {
224	            console.error('WebRTC initialization failed:', err);
225	            setError('Failed to initialize video chat. You can still play without video.');
226	          }
227	        })
228	      );
229	
230	      unsubscribers.push(
231	        socketService.on('gameStart', (data: { color: 'white' | 'black' }) => {
232	          console.log('Game started:', data);
233	          setGameState((prev) => ({
234	            ...prev,
235	            isPlaying: true,
236	            playerColor: data.color,
237	            isMyTurn: data.color === 'white',
238	            gameOver: false,
239	            winner: null,
240	            gameOverReason: null,
241	          }));
242	          chess.reset();
243	        })
244	      );
245	
246	      unsubscribers.push(
247	        socketService.on('opponentMove', (data: { move: string; fen: string; isWhite: boolean }) => {
248	          console.log('Opponent move:', data);
249	          
250	          try {
251	            chess.move({ from: data.move.substring(0, 2), to: data.move.substring(2, 4), promotion: 'q' });
252	            
253	            setGameState((prev) => ({
254	              ...prev,
255	              fen: data.fen,
256	              isMyTurn: true,
257	            }));
258	
259	            // Check for game over
260	            if (chess.isGameOver()) {
261	              let winner: 'white' | 'black' | 'draw' | null = null;
262	              let reason = '';
263	
264	              if (chess.isCheckmate()) {
265	                winner = chess.turn() === 'w' ? 'black' : 'white';
266	                reason = 'checkmate';
267	              } else if (chess.isDraw()) {
268	                reason = 'draw';
269	              }
270	
271	              setGameState((prev) => ({
272	                ...prev,
273	                gameOver: true,
274	                winner,
275	                gameOverReason: reason,
276	              }));
277	            }
278	          } catch (err) {
279	            console.error('Error processing opponent move:', err);
280	          }
281	        })
282	      );
283	
284	      unsubscribers.push(
285	        socketService.on('gameOver', (data: { reason: string; winner: 'white' | 'black' }) => {
286	          console.log('Game over:', data);
287	          setGameState((prev) => ({
288	            ...prev,
289	            isPlaying: false,
290	            gameOver: true,
291	            winner: data.winner,
292	            gameOverReason: data.reason,
293	          }));
294	        })
295	      );
296	
297	      unsubscribers.push(
298	        socketService.on('error', (data: { message: string }) => {
299	          console.error('Server error:', data);
300	          setError(data.message);
301	        })
302	      );
303	
304	      unsubscribers.push(
305	        socketService.on('chatMessage', (data: ChatMessage) => {
306	          setChatMessages((prev) => [...prev, { ...data, isMe: data.from === socketService.getId() }]);
307	        })
308	      );
309	
310	      unsubscribers.push(
311	        socketService.on('webrtc-offer', async (data: { offer: RTCSessionDescriptionInit; from: string }) => {
312	          console.log('Received WebRTC offer');
313	          try {
314	            const answer = await webRTCService.createAnswer(data.offer);
315	            if (gameState.game) {
316	              socketService.sendWebRTCAnswer(gameState.game.id, answer, socketService.getId()!);
317	            }
318	          } catch (err) {
319	            console.error('Error creating answer:', err);
320	          }
321	        })
322	      );
323	
324	      unsubscribers.push(
325	        socketService.on('webrtc-answer', async (data: { answer: RTCSessionDescriptionInit }) => {
326	          console.log('Received WebRTC answer');
327	          try {
328	            await webRTCService.setAnswer(data.answer);
329	          } catch (err) {
330	            console.error('Error setting answer:', err);
331	          }
332	        })
333	      );
334	
335	      unsubscribers.push(
336	        socketService.on('webrtc-ice-candidate', async (data: { candidate: RTCIceCandidateInit }) => {
337	          try {
338	            await webRTCService.addIceCandidate(data.candidate);
339	          } catch (err) {
340	            console.error('Error adding ICE candidate:', err);
341	          }
342	        })
343	      );
344	    };
345	
346	    if (gameState.isConnected) {
347	      setupListeners();
348	    }
349	
350	    return () => {
351	      unsubscribers.forEach((unsub) => unsub());
352	    };
353	  }, [gameState.isConnected, gameState.game, chess]);
354	
355	  const value = {
356	    gameState,
357	    chess,
358	    connect,
359	    disconnect,
360	    joinQueue,
361	    leaveQueue,
362	    makeMove,
363	    resign,
364	    sendChatMessage,
365	    chatMessages,
366	    localVideoStream,
367	    remoteVideoStream,
368	    isVideoEnabled,
369	    isAudioEnabled,
370	    toggleVideo,
371	    toggleAudio,
372	    switchCamera,
373	    error,
374	    clearError,
375	  };
376	
377	  return <GameContext.Provider value={value}>{children}</GameContext.Provider>;
378	}
379	
380	export function useGame() {
381	  const context = useContext(GameContext);
382	  if (context === undefined) {
383	    throw new Error('useGame must be used within a GameProvider');
384	  }
385	  return context;
386	}

