1	import { io, Socket } from 'socket.io-client';
2	
3	const SERVER_URL = import.meta.env.VITE_SERVER_URL || 'http://localhost:3001';
4	
5	class SocketService {
6	  private socket: Socket | null = null;
7	  private listeners: Map<string, Set<Function>> = new Map();
8	
9	  connect(): Promise<void> {
10	    return new Promise((resolve, reject) => {
11	      this.socket = io(SERVER_URL, {
12	        transports: ['websocket', 'polling'],
13	        reconnection: true,
14	        reconnectionAttempts: 5,
15	        reconnectionDelay: 1000,
16	      });
17	
18	      this.socket.on('connect', () => {
19	        console.log('Connected to server:', this.socket?.id);
20	        resolve();
21	      });
22	
23	      this.socket.on('connect_error', (error) => {
24	        console.error('Connection error:', error);
25	        reject(error);
26	      });
27	
28	      this.socket.on('disconnect', (reason) => {
29	        console.log('Disconnected from server:', reason);
30	      });
31	
32	      // Set up event listeners
33	      this.setupEventListeners();
34	    });
35	  }
36	
37	  private setupEventListeners() {
38	    if (!this.socket) return;
39	
40	    const events = [
41	      'queueJoined',
42	      'queueLeft',
43	      'matchFound',
44	      'gameStart',
45	      'opponentMove',
46	      'gameOver',
47	      'error',
48	      'chatMessage',
49	      'webrtc-offer',
50	      'webrtc-answer',
51	      'webrtc-ice-candidate',
52	    ];
53	
54	    events.forEach((event) => {
55	      this.socket!.on(event, (data) => {
56	        this.emit(event, data);
57	      });
58	    });
59	  }
60	
61	  private emit(event: string, data: any) {
62	    const listeners = this.listeners.get(event) || new Set();
63	    listeners.forEach((listener) => listener(data));
64	  }
65	
66	  on(event: string, callback: Function): () => void {
67	    if (!this.listeners.has(event)) {
68	      this.listeners.set(event, new Set());
69	    }
70	    this.listeners.get(event)!.add(callback);
71	
72	    // Return unsubscribe function
73	    return () => {
74	      this.listeners.get(event)?.delete(callback);
75	    };
76	  }
77	
78	  joinQueue() {
79	    this.socket?.emit('joinQueue');
80	  }
81	
82	  leaveQueue() {
83	    this.socket?.emit('leaveQueue');
84	  }
85	
86	  makeMove(gameId: string, move: string, fen: string) {
87	    this.socket?.emit('makeMove', { gameId, move, fen });
88	  }
89	
90	  resign(gameId: string) {
91	    this.socket?.emit('resign', { gameId });
92	  }
93	
94	  sendChatMessage(gameId: string, message: string) {
95	    this.socket?.emit('chatMessage', { gameId, message });
96	  }
97	
98	  // WebRTC signaling
99	  sendWebRTCOffer(gameId: string, offer: RTCSessionDescriptionInit, from: string) {
100	    this.socket?.emit('webrtc-offer', { gameId, offer, from });
101	  }
102	
103	  sendWebRTCAnswer(gameId: string, answer: RTCSessionDescriptionInit, from: string) {
104	    this.socket?.emit('webrtc-answer', { gameId, answer, from });
105	  }
106	
107	  sendWebRTCIceCandidate(gameId: string, candidate: RTCIceCandidateInit, from: string) {
108	    this.socket?.emit('webrtc-ice-candidate', { gameId, candidate, from });
109	  }
110	
111	  disconnect() {
112	    this.socket?.disconnect();
113	    this.socket = null;
114	    this.listeners.clear();
115	  }
116	
117	  getId(): string | undefined {
118	    return this.socket?.id;
119	  }
120	
121	  isConnected(): boolean {
122	    return this.socket?.connected || false;
123	  }
124	}
125	
126	export const socketService = new SocketService();

