1	class WebRTCService {
2	  private peerConnection: RTCPeerConnection | null = null;
3	  private localStream: MediaStream | null = null;
4	  private remoteStream: MediaStream | null = null;
5	  private onRemoteStreamCallback: ((stream: MediaStream) => void) | null = null;
6	  private onIceCandidateCallback: ((candidate: RTCIceCandidateInit) => void) | null = null;
7	
8	  async initialize(onRemoteStream: (stream: MediaStream) => void, onIceCandidate: (candidate: RTCIceCandidateInit) => void): Promise<MediaStream> {
9	    this.onRemoteStreamCallback = onRemoteStream;
10	    this.onIceCandidateCallback = onIceCandidate;
11	
12	    // Create peer connection
13	    this.peerConnection = new RTCPeerConnection({
14	      iceServers: [
15	        { urls: 'stun:stun.l.google.com:19302' },
16	        { urls: 'stun:stun1.l.google.com:19302' },
17	      ],
18	    });
19	
20	    // Get local media stream
21	    try {
22	      this.localStream = await navigator.mediaDevices.getUserMedia({
23	        video: {
24	          width: { ideal: 640 },
25	          height: { ideal: 480 },
26	          facingMode: 'user',
27	        },
28	        audio: true,
29	      });
30	
31	      // Add local stream tracks to peer connection
32	      this.localStream.getTracks().forEach((track) => {
33	        if (this.peerConnection) {
34	          this.peerConnection.addTrack(track, this.localStream!);
35	        }
36	      });
37	
38	      // Set up remote stream handler
39	      this.peerConnection.ontrack = (event) => {
40	        if (this.onRemoteStreamCallback) {
41	          this.remoteStream = event.streams[0];
42	          this.onRemoteStreamCallback(this.remoteStream);
43	        }
44	      };
45	
46	      // Set up ICE candidate handler
47	      this.peerConnection.onicecandidate = (event) => {
48	        if (event.candidate && this.onIceCandidateCallback) {
49	          this.onIceCandidateCallback(event.candidate.toJSON());
50	        }
51	      };
52	
53	      return this.localStream;
54	    } catch (error) {
55	      console.error('Error accessing media devices:', error);
56	      throw error;
57	    }
58	  }
59	
60	  async createOffer(): Promise<RTCSessionDescriptionInit> {
61	    if (!this.peerConnection) {
62	      throw new Error('Peer connection not initialized');
63	    }
