2	  private peerConnection: RTCPeerConnection | null = null;
3	  private localStream: MediaStream | null = null;
4	  private remoteStream: MediaStream | null = null;
5	  private onRemoteStreamCallback: ((stream: MediaStream) => void) | null = null;
6	  private onIceCandidateCallback: ((candidate: RTCIceCandidateInit) => void) | null = null;
7	
8	  async initialize(onRemoteStream: (stream: MediaStream) => void, onIceCandidate: (candidate: RTCIceCandidateInit) => void): Promise<MediaStream> {
9	    this.onRemoteStreamCallback = onRemoteStream;
10	    this.onIceCandidateCallback = onIceCandidate;
11	
12	    // Create peer connection
13	    this.peerConnection = new RTCPeerConnection({
14	      iceServers: [
15	        { urls: 'stun:stun.l.google.com:19302' },
16	        { urls: 'stun:stun1.l.google.com:19302' },
17	      ],
18	    });
19	
20	    // Get local media stream
21	    try {
22	      this.localStream = await navigator.mediaDevices.getUserMedia({
