      });

      expect(screen.getByClassName('game-area')).toBeInTheDocument();
      expect(screen.getByClassName('sidebar')).toBeInTheDocument();
    });
  });

  describe('Component Integration', () => {
    it('should integrate ChessBoardPanel component', async () => {
