  const chess2 = new Chess();
  chess2.move('e4');
  chess2.move('d5'); // Black plays d7-d5
  // Now white can capture en passant: exd5
  const move = chess2.move('exd6'); // This should be exd5 (capturing the pawn)
  // Actually after e4 d5, white plays exd5 (regular capture)
