  chess3.move('e4');
  chess3.move('e5');
  chess3.move('d4');
  chess3.move('d5'); // Black plays d7-d5
  // Now white can capture en passant with e4xd5
  const epMove = chess3.move('exd6'); // e5xd6 en passant
  expect(epMove).toBeTruthy();
  expect(epMove.flags).toContain('e');
});

