  // But for en passant, the capturing pawn must be on the 5th rank
  // So after e4 e5 d4 d5, white plays exd5 (regular capture, not en passant)
  // For en passant: white pawn on e5, black plays d7-d5, white plays exd6
  const chess4 = new Chess();
  chess4.move('e4');
