  chess4.move('e5'); // e4-e5 (now white pawn on 5th rank)
  chess4.move('d4'); // This doesn't work
  // Let's do it properly:
  const chess5 = new Chess();
  chess5.move('d4'); // d2-d4
  chess5.move('d5'); // d7-d5
  chess5.move('e4'); // e2-e4
